CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('ADMIN','OPERATIONS_MANAGER','FIELD_ENGINEER')));
CREATE TABLE wells (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL, api_gravity NUMERIC(4,1), reservoir_temperature NUMERIC(5,2), reservoir_pressure NUMERIC(7,2), viscosity_cp NUMERIC(10,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reservoir_data (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), recorded_at TIMESTAMPTZ NOT NULL, reservoir_temperature NUMERIC(5,2), reservoir_pressure NUMERIC(7,2), bottomhole_pressure NUMERIC(7,2), oil_viscosity_cp NUMERIC(10,2), fluid_level_m NUMERIC(7,2));
CREATE TABLE production_data (id BIGSERIAL PRIMARY KEY, well_id TEXT REFERENCES wells(id), recorded_at TIMESTAMPTZ NOT NULL, oil_bopd NUMERIC(8,2), water_cut NUMERIC(5,2), energy_kwh_bbl NUMERIC(8,2));
CREATE TABLE css_cycles (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), cycle_no INTEGER NOT NULL, steam_ton NUMERIC(8,2), injection_pressure_bar NUMERIC(6,2), injection_hours NUMERIC(6,2), soak_hours NUMERIC(6,2), production_cutoff_bopd NUMERIC(8,2), started_at TIMESTAMPTZ, UNIQUE(well_id, cycle_no));
CREATE TABLE srp_data (id BIGSERIAL PRIMARY KEY, well_id TEXT REFERENCES wells(id), recorded_at TIMESTAMPTZ NOT NULL, spm NUMERIC(5,2), stroke_in NUMERIC(5,2), vfd_hz NUMERIC(5,2), rod_load_kn NUMERIC(7,2), pump_fillage NUMERIC(5,2));
CREATE TABLE rod_events (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), detected_at TIMESTAMPTZ NOT NULL, event_type TEXT NOT NULL, severity TEXT NOT NULL, rod_load_kn NUMERIC(7,2), pump_fillage NUMERIC(5,2), details JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'OPEN');
CREATE TABLE pump_events (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), detected_at TIMESTAMPTZ NOT NULL, event_type TEXT NOT NULL, severity TEXT NOT NULL, pump_depth_m NUMERIC(7,2), details JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'OPEN');
CREATE TABLE failure_predictions (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), predicted_at TIMESTAMPTZ NOT NULL DEFAULT now(), failure_type TEXT NOT NULL, risk_probability NUMERIC(5,4) NOT NULL CHECK (risk_probability BETWEEN 0 AND 1), expected_window TEXT, contributing_factors JSONB NOT NULL DEFAULT '[]'::jsonb, recommended_inspection TEXT);
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, well_id TEXT REFERENCES wells(id), severity TEXT NOT NULL, category TEXT NOT NULL, detected_at TIMESTAMPTZ NOT NULL, condition TEXT NOT NULL, recommendation TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN');
CREATE TABLE ai_recommendations (id BIGSERIAL PRIMARY KEY, well_id TEXT REFERENCES wells(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), recommendation TEXT NOT NULL, reason TEXT NOT NULL, predicted_impact TEXT NOT NULL, confidence NUMERIC(4,3), status TEXT NOT NULL DEFAULT 'PENDING');
CREATE TABLE maintenance_records (id BIGSERIAL PRIMARY KEY, well_id TEXT NOT NULL REFERENCES wells(id), scheduled_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, maintenance_type TEXT NOT NULL, assigned_to BIGINT REFERENCES users(id), notes TEXT, outcome TEXT);
CREATE INDEX reservoir_well_time_idx ON reservoir_data(well_id, recorded_at DESC);
CREATE INDEX production_well_time_idx ON production_data(well_id, recorded_at DESC);
CREATE INDEX srp_well_time_idx ON srp_data(well_id, recorded_at DESC);
CREATE INDEX alerts_status_time_idx ON alerts(status, detected_at DESC);
CREATE INDEX rod_events_well_time_idx ON rod_events(well_id, detected_at DESC);
CREATE INDEX pump_events_well_time_idx ON pump_events(well_id, detected_at DESC);
CREATE INDEX failure_predictions_well_time_idx ON failure_predictions(well_id, predicted_at DESC);
CREATE INDEX css_cycles_well_cycle_idx ON css_cycles(well_id, cycle_no DESC);
